function validate([num1, num2]) {
  for (const num of [num1, num2]) {
    const match = typeof num === 'string' && num.match(/^(0|-?[1-9]\d*)\+(0|-?[1-9]\d*)i$/);
    if (!match) return 'Each number looks like "a+bi", for example "3+-4i".';
    if (Math.abs(Number(match[1])) > 100 || Math.abs(Number(match[2])) > 100) return 'Each part is between -100 and 100.';
  }
  return null;
}

