function complexNumberMultiply(num1, num2) {
  const parse = (num) => {
    const plus = num.indexOf('+');
    const real = Number(num.slice(0, plus));
    const imaginary = Number(num.slice(plus + 1, num.length - 1));
    return [real, imaginary];
  };

  const [a, b] = parse(num1);
  const [c, d] = parse(num2);
  const real = a * c - b * d;
  const imaginary = a * d + b * c;
  return `${real}+${imaginary}i`;
}

