function complexNumberMultiply(num1, num2) {
  // Expand (a + bi)(c + di) term by term as a polynomial in i, then fold i^2 into -1.
  const read = (s) => s.match(/^(-?\d+)\+(-?\d+)i$/).slice(1).map((t) => parseInt(t, 10));
  const x = read(num1), y = read(num2);
  const power = [0, 0, 0];
  for (let p = 0; p < 2; p++) for (let q = 0; q < 2; q++) power[p + q] += x[p] * y[q];
  const re = power[0] - power[2], im = power[1];
  return String(re === 0 ? 0 : re) + '+' + String(im === 0 ? 0 : im) + 'i';
}

