function generate(rand, size) {
  const span = size === 'large' ? 100 : 6;
  const part = () => {
    if (rand() < 0.15) return [0, 100, -100][Math.floor(rand() * 3)];
    return Math.floor(rand() * (2 * span + 1)) - span;
  };
  const make = () => `${part()}+${part()}i`;
  return [make(), make()];
}
